      "복제 조인(맵 사이드 조인): 작은 데이터셋을 모든 맵 태스크의 메모리에 복제해 맵 단계에서 결합한다 — 셔플·리듀스가 없어 빠르다.",
      "복합 조인(같은 방식으로 미리 정렬·분할된 대용량 데이터끼리)과 카티션 곱(모든 쌍 조합)도 조인 패턴에 속한다.",
      "기출(6회·12회): '두 데이터셋을 키 기준으로 결합/다른 데이터와 연결해 분석하는 패턴' → 조인 패턴(요약·필터링 패턴은 오답)."
