      "제품(Product): 생산·제공하는 제품·서비스 개선 관련 주제(예: 제품 주요 기능 개선, 서비스 모니터링 지표 도출).",
      "고객(Customer): 사용자·고객과 이를 제공하는 채널 관점의 주제(예: 고객 대기 시간 최소화, 영업점 위치 최적화).",
      "규제와 감사(Regulation & Audit): 생산·전달 과정의 규제·보안 관점(예: 서비스 품질 이상 징후 관리) / 지원 인프라(IT & Human Resource): 시스템과 운영 인력 관점(예: EDW 최적화, 적정 운영 인력 도출).",
      "원형은 오스터왈더의 9개 블록(고객 세그먼트·가치 제안·채널·고객 관계·수익원·핵심 자원·핵심 활동·핵심 파트너·비용 구조)이다."
