      "내재화: 방법론이 개인에게 전파·활용되며 다시 암묵지로 체득되고, 이 순환이 반복되며 방법론이 고도화된다.",
      "노나카의 SECI 모델(공통화·표출화·연결화·내면화)과 같은 암묵지–형식지 순환 원리다."
