      "미국 교육부 기준 예: k=3은 안전도를 보장하는 최소 수준, 5≤k≤10은 높은 수준 — 계량 분석으로 산출한 k값이 평가 기준값 이상이면 '적정'",
      "한계: 민감정보의 다양성과 공격자의 배경지식을 고려하지 않아 동질성 공격·배경지식 공격에 취약 → 'k-익명성은 언제나 신뢰할 만하다'는 틀린 진술(13회)"
